import java.io.*;
import java.util.*;

public class VanyaAndScale {
    static long[] a;
    static boolean ans;
    static int n;
    static long leftSum, rightSum;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long w = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        long limit = (long) 1e11;
        a = new long[40];
        int z = 1;
        long temp = 1;
        a[0] = 1;
        if (w <= 3) {
            System.out.println("YES");
            return;
        }
        for (int i = 1; i < 16; i++) {
            a[z] = temp * w;
            temp *= w;
            if (temp > limit) break;
            z++;
        }
        leftSum = 0;
        rightSum = m;
        n = z;
        ans = false;
        explore(0);
        System.out.println(ans ? "YES" : "NO");
    }

    static void explore(int index) {
        if (index == n) {
            if (leftSum == rightSum) {
                ans = true;
            }
            return;
        }
        if (ans) return;
        for (int i = 0; i < 3; i++) {
            if (ans) return;
            switch (i) {
                case 1:
                    leftSum += a[index];
                    explore(index + 1);
                    leftSum -= a[index];
                    break;
                case 2:
                    rightSum += a[index];
                    explore(index + 1);
                    rightSum -= a[index];
                    break;
                default:
                    explore(index + 1);
            }
        }
    }
}
